#!/usr/bin/env ruby
# encoding: UTF-8
# frozen_string_literal: true

# Business-specific invariants only. Run the Builder validator separately for
# the v2 package schema, Open Web rewrite and graph consistency checks.
require "yaml"

skill_dir = File.expand_path(ARGV.fetch(0, ".."), __dir__)
contract = YAML.safe_load(File.read(File.join(skill_dir, "references/api-contract.yaml"), encoding: "UTF-8"), aliases: false)
recipes = contract.fetch("recipes")
aggregation = contract.dig("orchestration", "aggregation")
errors = []
assert = ->(condition, message) { errors << message unless condition }

assert.call(aggregation["source_recipe"] == "process_records", "精细分析必须来自流程原始任务记录")
assert.call(aggregation["processor"] == "scripts/analyze_records.py", "必须使用已测试的本地明细处理器")
assert.call(aggregation["scan_sections"] == %w[done todo], "已办可能合并到 todo，必须遍历 done 与 todo")
assert.call(aggregation["excluded_sections"] == ["forecast"], "不能把预测任务计入效率样本")
assert.call(aggregation["node_type_codes"] == [1, 2, 3], "仅审批、盖章、归档节点参与统计")
assert.call(aggregation["completed_status_codes"] == [1, 2], "有效已处理任务仅允许完成或拒绝状态")
assert.call(aggregation["handled_command_codes"] == [1, 2, 10], "默认动作仅同意、拒绝、加签同意")
assert.call(aggregation["deduplication_key"] == %w[processInstanceId processTaskInstanceId], "必须以流程实例与任务实例去重，不能按 nodeId 去重")
assert.call(aggregation.dig("time_window", "field") == "endTime" && aggregation.dig("time_window", "bounds") == "[start,end)", "明细按任务结束时间半开区间筛选")
assert.call(aggregation.dig("duration", "unit") == "seconds" && aggregation.dig("duration", "calendar") == "natural_elapsed", "原始计算单位必须为自然秒")
assert.call(aggregation.dig("duration", "formula") == "endTime - createTime", "任务用时必须由结束减创建计算")
assert.call(aggregation.dig("duration", "forbidden_duration_fields") == %w[createTimeSpan endTimeSpan], "相对当前时刻的 span 不是任务耗时")
assert.call(aggregation.dig("mean", "denominator") == "valid_completed_tasks", "均值分母必须为有效已处理任务数，不能平均各组均值")
assert.call(aggregation.dig("mean", "pending_in_denominator") == false && aggregation.dig("mean", "empty") == 0, "在途不进入均值；用户要求的无样本聚合展示为0")
assert.call(aggregation.fetch("mean").key?("detail_missing_duration") && aggregation.dig("mean", "detail_missing_duration").nil?, "单条明细缺失耗时必须保持null，不能沿用聚合展示0")
assert.call(aggregation.dig("mean", "node_mean_is") == "task_average_not_parallel_node_wall_clock", "节点表必须标任务均值，不能伪造并行节点墙钟时长")
assert.call(aggregation.dig("groups", "by_process_node") == %w[processDefinitionId nodeId nodeTypeCode], "不同流程定义/版本与节点不可混合；合同分类不能代替流程定义")
assert.call(aggregation.dig("attribution", "department_basis") == "CURRENT", "员工部门仅证明当前归属")
assert.call(aggregation.dig("attribution", "multiple_departments") == "COMPOSITE_BUCKET_NO_DUPLICATION", "多部门不得重复全额计数")
assert.call(aggregation.dig("attribution", "multiple_assignees") == "ATTRIBUTE_BY_PERSON_TASK_CENTER_OTHERWISE_EXCLUDE_PERSONAL", "多人节点须先按个人任务中心归因，仍无法归因时才排除")
attribution = aggregation.fetch("attribution")
assert.call(attribution["personal_node_policy"] == "SOURCE_TASK_ATTRIBUTION_FIRST_HISTORY_SINGLETON_FALLBACK", "个人统计必须优先使用原始个人任务，缺失时才回退历史单人证据")
source_attribution = attribution.fetch("source_task_attribution")
assert.call(source_attribution["input"] == "bundle.task_records" && source_attribution["key"] == %w[process_instance_id task_instance_id] && source_attribution["employee_ids"] == "discovered_for_employee_ids", "原始任务归因必须按流程实例与任务ID连接目标人员")
assert.call(source_attribution["completed_requires_unique_person"] == true && source_attribution["auto_end_or_nonhuman_action_excluded"] == true, "已办归因须唯一，自动结束等非人工动作不能计入")
assert.call(attribution["node_key"] == %w[processInstanceId processDefinitionId nodeId nodeTypeCode], "多人识别不能跨流程实例或版本合并节点")
assert.call(attribution["participant_union_scope"] == "ALL_DONE_TODO_RECORDS_AND_PARENT_ASSIGNEES_BEFORE_LOCAL_FILTERS", "必须先汇总整个节点人员，再按人员/时间/动作筛选")
assert.call(attribution["mode_proves_count"] == false, "taskModeCode只能表示模式，不能证明人数")
assert.call(attribution["missing_round_id"] == "CONSERVATIVELY_MERGE_SAME_INSTANCE_DEFINITION_NODE", "无可靠节点轮次时须保守合并并披露")
assert.call(attribution["unknown_participant_count"] == "EXCLUDE_PERSONAL_WITH_SEPARATE_DIAGNOSTIC", "人数未知不能冒充单人，应排除个人统计并单列")
participant_evidence = attribution.fetch("participant_evidence")
assert.call(participant_evidence["input"] == "bundle.node_participant_evidence" && participant_evidence["key"] == %w[processInstanceId processDefinitionId nodeId], "人数证据必须绑定真实实例、定义与节点")
assert.call(%w[complete_required nonempty_source_required single_required observed_must_be_subset fabricated_completeness_forbidden].all? { |key| participant_evidence[key] == true }, "完整单人证据必须来源可核验、人员唯一且覆盖可见记录，不能猜测完整性")
assert.call(participant_evidence["conflicting_evidence"] == "REJECT_INPUT", "同节点证据冲突必须拒绝输入")
assert.call(participant_evidence["complete_runtime_recipe_verified"] == true && participant_evidence["complete_runtime_recipe_scope"] == "EXACT_HISTORICAL_FIXED_SINGLETON_NO_REASSIGNMENT", "已验证补证仅限精确历史固定单人且无转办等变更的节点")
assert.call(participant_evidence["participant_api_alone_proves_complete"] == false, "人员映射或实例已办人列表不能单独证明历史节点完整人数")
assert.call(aggregation.dig("business_identity", "precedence") == "RECORD_BUSINESS_ID_AND_TYPE_FIRST" && aggregation.dig("business_identity", "wrapper_fallback") == "ONLY_SAME_PROCESS_INSTANCE", "历史任务归属优先record业务字段，外层仅同PID时可回退")
assert.call(aggregation.dig("business_identity", "invented_id_or_name_allowed") == false, "不得虚构历史业务ID、合同名称或编号")
assert.call(aggregation.dig("count_units", "contract_deduplication_key") == %w[businessTypeCode businessId] && aggregation.dig("count_units", "handled_counts") == "UNIQUE_VALID_COMPLETED_TASKS", "合同数与处理次数必须使用不同计数单位")
assert.call(aggregation.dig("roster", "source") == "bundle.employees" && aggregation.dig("roster", "initialize_all_selected_people_and_stages") == true && aggregation.dig("roster", "default_stage_codes") == [1, 2, 3], "完整人员清单中的每人在三个阶段均须保留零样本行")
assert.call(aggregation.dig("coverage", "full_population_guaranteed") == false && aggregation.dig("coverage", "history_complete_guaranteed") == false, "样本发现与关联历史流程均不得宣称全量保证")

assert.call(recipes["efficiency_contracts"]["role"] == "OPTIONAL" && recipes["efficiency_contracts"]["required"] == false, "盖章日期发现必须可选，显式业务清单不能被强制盖章筛选")
assert.call(recipes.dig("efficiency_contracts", "parameters", "startDate", "from") == "inputs.discovery_start", "发现日期和任务完成窗口必须独立")
assert.call(recipes.dig("efficiency_contracts", "parameters", "endDate", "from") == "inputs.discovery_end", "发现结束日期不能悄然复用任务结束窗口")
assert.call(recipes.dig("efficiency_contracts", "response", "pagination", "has_next_reliable") == false && recipes.dig("efficiency_contracts", "response", "pagination", "total_pages_reliable") == false, "看板 hasNext 与 totalPages 不可作为唯一完整性依据")
assert.call(recipes.dig("contract_info", "parameters", "tianyancha", "value") == false, "普通合同详情禁用额外外部企业查询")
assert.call(recipes.dig("contract_info", "parameters", "generateContractName", "value") == false, "普通合同详情不得触发名称重生成")
assert.call(recipes.dig("assembly_info", "parameters", "needChildrenInfo", "value") == false, "合同组详情不加载无关子合同")
assert.call(recipes.dig("employees", "parameters", "extraDepartmentInfo", "value") == true, "可选员工补全需请求部门详情")
assert.call(recipes.dig("employees", "role") == "OPTIONAL", "人员查询仅作缺失部门的可选补全")

recipes.each do |name, recipe|
  assert.call(recipe.dig("parameters", "Timezone-Offset", "value") == -480, "#{name} 必须显式请求 UTC+8 无时区时间序列化")
  assert.call(recipe.dig("operation", "read_or_write") == "READ", "本 Skill 不得包含业务写操作")
  assert.call(recipe.dig("operation", "identity") == "USER", "必须复用用户身份，不切应用身份扩大范围")
  method = recipe.dig("endpoint", "method")
  assert.call(method == "GET" || (%w[efficiency_contracts participant_contracts].include?(name) && method == "POST"), "POST仅限只读看板发现与参与合同搜索")
end

discovery = contract.dig("orchestration", "discovery")
assert.call(discovery["processor"] == "scripts/discover_businesses.py", "姓名/部门发现必须使用受控发现helper")
assert.call((%w[employees businesses approver_ids coverage diagnostics continuation process_instances task_records] - discovery["outputs"]).empty?, "发现结果必须保留原始任务、实例、人员、业务、覆盖诊断和续读状态")
assert.call(discovery["identity_namespace"] == "EMPLOYEE_ID_FOR_ANALYSIS_DIRECTORY_LARK_ID_FOR_BPM_QUERY", "审批统计用employeeId，原始任务query必须用目录真实larkId")
assert.call(discovery["default_candidate_source"] == "raw-tasks" && discovery["participation_index_is_required_filter"] == false, "默认发现不得依赖会漏项的APPROVE_AUTHORITY")
raw_tasks = recipes.fetch("raw_person_tasks")
assert.call(raw_tasks.dig("endpoint", "open_web_path") == "/open-web/web/clm-openapi/v1/tasks/getTasks", "须经已验证的OpenWeb原始任务入口")
assert.call(raw_tasks.dig("response", "pagination", "termination") == "EMPTY_PAGE" && raw_tasks.dig("response", "pagination", "short_page_is_complete") == false, "原始任务首批短页不得提前结束")
assert.call(discovery["input_modes"] == %w[employee_name department_name resume_file] && discovery["input_modes_mutually_exclusive"] == true, "姓名、部门、合同分页续读必须为互斥入口")
assert.call(discovery["name_ambiguity"] == "REQUIRE_SELECTION", "同名人员/部门必须消歧，不能自动选择首项")
assert.call(contract.dig("inputs", "include_subdepartments", "default") == true, "部门发现默认包含已发现子部门")
assert.call(discovery["employee_deduplication_key"] == "employeeId" && discovery["department_deduplication_key"] == "departmentId", "当前成员和部门须按内部ID去重并防环")
assert.call(discovery["business_deduplication_key"] == %w[businessTypeCode businessId], "合并业务必须按类型和业务ID去重，不能用groupId替代")
assert.call(discovery["resolve_only_preserves_explicit_business_scope"] == true, "用户明确合同范围时仅解析目标人员，不扩大合同发现范围")
assert.call(discovery["resume_scope"] == "SAME_SOURCE_PERSON_STATUS_CURSOR_ONLY", "续读须同源并按人员/状态隔离游标，不能复用旧索引或恢复组织缺口")
assert.call(discovery["per_employee_limits"] == %w[max_pages max_businesses], "累计页数与业务上限按人员计算，不能误标为全局上限")
%w[max_businesses max_pages max_member_pages max_departments].each do |limit|
  assert.call(contract.dig("inputs", limit, "default") == 0, "#{limit}默认必须为0不限，不能静默截取样本")
end
assert.call(discovery["default_limits"] == 0 && discovery["zero_limit_semantics"] == "UNLIMITED_UNTIL_PAGINATION_COMPLETE_OR_ERROR" && discovery["positive_limits"] == "EXPLICIT_USER_TRIAL_ONLY", "发现默认完整翻页，仅用户显式正数可限制试跑")
assert.call(!contract.fetch("inputs").fetch("trial_max_businesses").key?("default"), "不能默认只抽取三份业务试跑")
assert.call(discovery["contract_date_filters_allowed"] == false && discovery["object_failure_falls_back_to_dashboard"] == false, "姓名/部门对象失败不能转盖章看板，也不能按合同日期过滤年度已处理任务")

lookup = recipes.fetch("employee_lookup")
assert.call(lookup.dig("parameters", "filterCurrentEmployee", "value") == false, "查询姓名不能排除当前操作者本人")
assert.call(lookup.dig("response", "selection", "forbidden_id_fields") == %w[openId userId], "不得用开放人员标识代替employeeId")
assert.call(lookup.dig("response", "selection", "departed_name_search_guaranteed") == false, "noFilterDeletedEmployee不能扩大为离职姓名检索保证")
department_lookup = recipes.fetch("department_lookup")
assert.call(department_lookup.dig("response", "selection", "forbidden_id_fields") == ["openDepartmentId"], "部门ID不得混用开放标识")
assert.call(department_lookup.dig("parameters", "showAllStatus", "effectiveness") == "CONFIRMED_IGNORED", "非空关键词查询不能宣称showAllStatus保证历史部门覆盖")
members = recipes.fetch("department_members").dig("response", "pagination")
assert.call(members["start_index"] == 1 && members["page_size"] == 50, "成员分页从1开始且不得超过后端50条上限")
assert.call(members["recursive"] == true && members["child_sources"] == %w[department_lookup.child_departments department_members.sub_departments], "直属成员为空也必须保留目录树和组织响应中的子部门递归")
assert.call(members["historical_membership_guaranteed"] == false, "当前部门成员不能伪装历史成员全量")

participant = recipes.fetch("participant_contracts")
semantics = participant.dig("response", "filter_semantics")
pagination = participant.dig("response", "pagination")
assert.call(semantics["search_field"] == "APPROVE_AUTHORITY" && semantics["operator"] == "SINGLE_EMPLOYEE_TERM", "参与合同搜索必须使用实际生效的逐人term")
assert.call(semantics["search_value_type"] == "scalar_string" && semantics["one_employee_per_request"] == true, "APPROVE_AUTHORITY不能传人员ID数组或逗号串")
assert.call(semantics["participation_only"] == true && semantics["completed_task_proof"] == false, "参与权限不能冒充实际已处理记录")
assert.call(semantics["contract_date_filters_allowed"] == false && semantics["task_window_applied_after_records"] == "endTime", "年度分析仅在任务记录阶段按endTime筛选")
assert.call(participant.dig("parameters", "conditionUnits", "value") == [], "参与合同候选不应夹带合同时间过滤条件")
assert.call(pagination["unit"] == "GROUPS" && pagination["count_is_contract_count"] == false && pagination["count_field"] == "filtered_group_count", "分页分母是合同组数量，不能用展开合同数判断完成")
assert.call(pagination["cursor_precision"] == "LOSSLESS_JSON" && pagination["cursor_scope"] == "ONE_EMPLOYEE", "searchAfter须无损且逐人隔离，不能用浮点或其他人的游标")
assert.call(pagination["group_deduplication_key"] == %w[employeeId groupId] && pagination["business_deduplication_key"] == %w[businessTypeCode contractId], "组分页去重和合同候选去重必须分别处理")
recovery = recipes.fetch("contract_brief_info").fetch("recovery")
assert.call(recovery["allowed_business_codes"] == [110002] && recovery["forbidden_business_codes"] == [110004], "轻量详情只能恢复系统错误，不得对无权限重试其他端点")
assert.call(recovery["process_instance_id_source"] == "response_only" && recovery["null_data"] == "UNRESOLVED_NOT_ZERO", "恢复流程ID必须来自响应，空响应不能伪造零处理")

assert.call(!recipes.key?("assigneeAggregation") && recipes.values.none? { |r| r.dig("endpoint", "open_web_path").include?("assigneeAggregation") }, "不能混入人员均值再平均的旧看板指标")
presentation = contract.fetch("presentation")
assert.call(presentation["schema_version"] == "2.2.1", "新报告使用schema2.2.1结构")
assert.call(presentation["default_sections"] == %w[overview_and_insights personal_stage_tables details_file], "默认输出总览与洞察、个人三阶段表、明细文件三个部分")
people_mode = presentation.dig("output_modes", "people")
range_mode = presentation.dig("output_modes", "department_or_other")
assert.call(contract.dig("inputs", "analysis_subject", "enum") == %w[people department other], "分析对象必须明确区分具体人员、部门和其他范围")
assert.call(people_mode["sections"] == %w[personal_stage_tables details_file] && people_mode["show_overview"] == false && people_mode["show_insights"] == false && people_mode["numbered_section_titles"] == false && people_mode["details_as_numbered_section"] == false, "具体人员模式只能展示个人三阶段表，不能出现总览、洞察或编号章节")
assert.call(people_mode["single_person_table"] == "COMBINE_NODE_TYPES_WITH_NODE_TYPE_COLUMN" && people_mode["multiple_people_tables"] == "SPLIT_BY_NODE_TYPE", "单人须合并三个节点，多人仍按节点分表")
assert.call(range_mode["sections"] == %w[overview_and_insights personal_stage_tables details_file] && range_mode["show_overview"] == true && range_mode["show_insights"] == true, "部门及其他范围必须保留总览、洞察和个人表")
assert.call(presentation.fetch("aggregate_tables").map { |t| t["key"] } == %w[overview by_approver], "默认聚合展示只包括总览与分阶段个人表")
assert.call(presentation.fetch("aggregate_tables").all? { |t| t["stage_codes"] == [1, 2, 3] }, "默认总览和个人表均覆盖审批、盖章、归档")
assert.call(presentation.fetch("additional_json_tables").map { |t| t["key"] } == %w[by_department by_process_node], "部门与流程节点表保留JSON兼容指标，不挤入默认展示")
assert.call(presentation["overview_columns"] == %w[node_type processed_contract_count approved_count rejected_count in_progress_contract_count total_seconds average_seconds], "总览须区分处理合同数、通过拒绝次数与在途合同数")
assert.call(presentation["personal_columns"] == %w[employee_name processed_contract_count approved_count rejected_count in_progress_count total_seconds average_seconds max_seconds min_seconds], "个人表必须保持用户指定九列")
personal_table = presentation.fetch("aggregate_tables").find { |t| t["key"] == "by_approver" }
assert.call(personal_table["display_employee_id"] == false && personal_table["all_roster_people"] == true && personal_table["split_tables_by"] == "node_type_code_unless_people_mode_has_one_roster_person", "个人表不展示人员ID；单人合表，多人分阶段并覆盖完整人员清单")
assert.call(presentation.dig("zero_samples", "aggregate_display") == 0 && presentation.dig("zero_samples", "unknown_or_denied_is_zero_data") == false, "无有效样本按要求显示0，但缺失与未授权不等于真实零数据")
details = presentation.fetch("details")
assert.call(details["source"] == "report.details" && details["processors"] == %w[scripts/export_details.py scripts/export_details.mjs], "明细文件必须来自同一报告并使用受控导出器")
assert.call(details["primary_format"] == "XLSX" && details["fallback_format"] == "CSV" && details["fallback_reason_required"] == true, "优先Excel，仅失败回退CSV并解释原因")
assert.call(details["user_columns"] == %w[contract_name contract_id contract_number node_name operator_name result created_at ended_at duration_seconds], "明细须保持用户指定九列")
assert.call(details["audit_columns"] == %w[node_type process_instance_id task_instance_id included_overview included_personal exclusion_reason], "明细需附类型、流程任务ID、计入统计标记与排除原因")
assert.call(details["include_personal_exclusions"] == true && details["include_pending"] == true && details["missing_time_or_duration"] == "KEEP_NULL_OR_EMPTY_NOT_ZERO" && details["id_cell_type"] == "TEXT", "明细应保留排除项和在途、缺时间留空、长ID写文本")
assert.call(recipes.dig("process_records", "response", "fields", "record_business_id", "path") == "$.data.{done,todo}[*].records[*].businessId", "采集契约必须保留record真实业务归属")
assert.call(recipes.key?("historical_node_people") && recipes.key?("historical_process_instance") && recipes.key?("historical_form_definition"), "人数补证必须包含实际历史实例、人员节点映射和匹配定义")
assert.call(contract.dig("presentation", "sample_label").include?("节点任务平均用时"), "报表必须清楚标明节点任务均值")

if errors.empty?
  puts "PASS    approval efficiency business invariants"
else
  errors.each { |error| warn "ERROR   #{error}" }
  exit 1
end
